program='''def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    # Bottom destination bands have a solid interior and matching side colors.
    bands={}
    r=0
    while r<h:
        if g[r][0]==g[r][-1] and len(set(g[r][1:-1]))==1:
            border,fill=g[r][0],g[r][1]
            r2=r
            while r2+1<h and g[r2+1]==g[r]: r2+=1
            if border!=fill and r2-r+1>=2:
                bands[fill]=(r,r2,border)
            r=r2+1
        else: r+=1
    first=min(v[0] for v in bands.values())
    bg=g[0][0]
    seen=set(); objects=[]
    for r in range(first):
        for c in range(w):
            if g[r][c]==bg or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        yy,xx=y+dy,x+dx
                        if 0<=yy<first and 0<=xx<w and g[yy][xx]!=bg and (yy,xx) not in seen:
                            seen.add((yy,xx)); stack.append((yy,xx))
            ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
            y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
            patch=[row[x0:x1+1] for row in g[y0:y1+1]]
            outline=patch[0][0]
            colors={v for row in patch for v in row if v!=bg}
            fill=next(iter(colors-{outline}),outline)
            if fill in bands:
                _,bottom,border=bands[fill]
                out=[row[:] for row in patch]
                for yy in range(len(out)):
                    for xx in range(len(out[0])):
                        if out[yy][xx]==outline: out[yy][xx]=border
                        elif out[yy][xx]!=bg: out[yy][xx]=fill
                dest=bottom-len(out)+1
                for yy,row in enumerate(out):
                    g[dest+yy][x0:x1+1]=row
    # Remove source objects.
    for r in range(first):
        for c in range(w):
            if g[r][c]!=bg: g[r][c]=bg
    return g
